// Browser-only endpoint rules. Packaged copies are generated by sync_endpoints.ts.
export const DEFAULT_API_BASE = "http://127.0.0.1:10012";
// Route-less operations accepted before the unified proxy keep their original destination.
export const LEGACY_API_BASE = "http://127.0.0.1:15012";
export const SITE_ORIGIN = "https://prometheus.cupofcup.chatgpt.site";
export const DEFAULT_CLOUD_BASE = SITE_ORIGIN;

function privateHost(hostname) {
  const host = hostname.replace(/^\[|\]$/g, "").toLowerCase();
  if (host === "localhost" || host === "::1") return true;
  if (/^(?:fc|fd)[0-9a-f]{2}:/.test(host) || /^fe[89ab][0-9a-f]:/.test(host)) {
    return true;
  }
  const parts = host.split(".").map(Number);
  return parts.length === 4 &&
    parts.every((part) => Number.isInteger(part) && part >= 0 && part <= 255) &&
    (parts[0] === 127 || parts[0] === 10 ||
      (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31) ||
      (parts[0] === 192 && parts[1] === 168) ||
      (parts[0] === 169 && parts[1] === 254));
}

export function validateApiBase(value) {
  if (typeof value !== "string" || !value.trim() || value.length > 2048) {
    throw new Error("API address is required");
  }
  const text = value.trim();
  if (
    !/^https?:\/\/[^/?#]+\/?$/i.test(text) || /[\s\\]/.test(value) ||
    Array.from(value).some((character) => character.charCodeAt(0) < 32)
  ) {
    throw new Error("API address must be a bare HTTP or HTTPS origin");
  }
  let url;
  try {
    url = new URL(text);
  } catch {
    throw new Error("API address is invalid");
  }
  if (
    url.username || url.password || url.search || url.hash ||
    url.pathname !== "/" || !url.hostname ||
    (url.protocol !== "http:" && url.protocol !== "https:")
  ) {
    throw new Error(
      "API address must not include credentials, path, query or fragment",
    );
  }
  if (url.protocol === "http:" && !privateHost(url.hostname)) {
    throw new Error(
      "HTTP requires a loopback or private LAN address; use HTTPS for a server",
    );
  }
  return url.origin;
}

export function validateCloudBase(value) {
  const origin = validateApiBase(value);
  if (!origin.startsWith("https://")) {
    throw new Error("Paired server address must use HTTPS");
  }
  return origin;
}

export function permissionOrigin(
  value,
  runtimeUrl = (globalThis.browser ?? globalThis.chrome)?.runtime?.getURL("") ??
    "",
) {
  const origin = validateApiBase(value);
  // Safari and Firefox reject ports in match patterns. Only their permission
  // envelope omits the port; the validated API destination remains exact.
  if (/^(?:moz-extension|safari-web-extension):\/\//.test(runtimeUrl)) {
    const url = new URL(origin);
    return `${url.protocol}//${url.hostname}/*`;
  }
  return origin + "/*";
}

export function parseEndpointInput(value) {
  if (typeof value === "string" && value.trim().startsWith("{")) {
    let descriptor;
    try {
      descriptor = JSON.parse(value);
    } catch {
      throw new Error("Server Info JSON is invalid");
    }
    return endpointFromServerInfo(descriptor);
  }
  return { apiBase: validateApiBase(value), mode: null, scope: null };
}

// The exact default remains declared; wildcard optional permissions are only a
// permission envelope, never discovery or a destination selection.
export function configuredCloudBase(manifest) {
  const exact = (manifest?.optional_host_permissions ?? []).filter((pattern) =>
    typeof pattern === "string" &&
    pattern.endsWith("/*") && !pattern.slice(0, -2).includes("*")
  );
  if (exact.length !== 1) {
    throw new Error("Exactly one default paired HTTPS origin is required");
  }
  return validateCloudBase(exact[0].slice(0, -2));
}

export function endpointFromServerInfo(value) {
  if (
    !value || value.version !== 1 || !value.endpoints || !value.identity
  ) {
    throw new Error("Unsupported Server Info descriptor");
  }
  const apiBase = validateApiBase(value.endpoints.api_base);
  const identity = value.identity;
  if (
    !["local", "cloud"].includes(identity.authority) ||
    ["owner_id", "dataset_id", "dataset_epoch"].some((key) =>
      typeof identity[key] !== "string" || !identity[key] ||
      identity[key].length > 128
    )
  ) throw new Error("Server Info identity is incomplete");
  const capture = value.capabilities?.capture;
  if (
    !capture || capture.available !== true ||
    capture.write_path !== "/api/preview/write" ||
    capture.readback_path !== "/api/preview/entries/:id" ||
    capture.identity_path !== "/api/identity" ||
    capture.prepare_path !== "/api/preview/bookmarks/parse" ||
    capture.tags_path !== "/api/preview/tags" ||
    capture.recent_path !== "/api/preview/recent" ||
    capture.methods?.write !== "POST" || capture.methods?.readback !== "GET" ||
    capture.methods?.identity !== "GET" ||
    capture.methods?.prepare !== "POST" ||
    capture.methods?.tags !== "GET" || capture.methods?.recent !== "GET" ||
    (identity.authority === "cloud" &&
      (capture.pairing_supported !== true ||
        capture.session_path !== "/api/session" ||
        capture.pair_claim_path !== "/api/pair/claim" ||
        capture.methods?.session !== "GET" ||
        capture.methods?.pair_claim !== "POST"))
  ) {
    throw new Error("This server does not declare supported capture delivery");
  }
  if (identity.authority === "cloud") validateCloudBase(apiBase);
  return {
    apiBase,
    mode: identity.authority,
    scope: Object.fromEntries(
      ["owner_id", "dataset_id", "dataset_epoch"].map((
        key,
      ) => [key, identity[key]]),
    ),
  };
}
